    # Nearest target helper
    def nearest(items, px, py):
        best = None
        best_d = None
        for item in items or []:
            if item is None:
                continue
            if isinstance(item, dict):
                p = item.get("pos", item.get("position", item.get("loc", None)))
            else:
                p = item
            if p is None:
                continue
            try:
                ix = int(p[0])
                iy = int(p[1])
            except Exception:
                continue
            d = abs(ix - px) + abs(iy - py)
            if best_d is None or d < best_d:
                best_d = d
                best = (ix, iy)
        return best, best_d

