    if board is None:
        board = g(observation, "grid", None)
    if board is None:
        board = g(observation, "map", None)

    width = g(observation, "width", None)
    height = g(observation, "height", None)
    if width is None or height is None:
        try:
            height = len(board)
            width = len(board[0]) if height else 0
        except Exception:
            width = width or 0
            height = height or 0

