        if e is None:
            continue
        try:
            if isinstance(e, dict):
                p = e.get("pos", e.get("position", e.get("loc", None)))
            else:
                p = e
            ex, ey = int(p[0]), int(p[1])
            enemy_set.add((ex, ey))
        except Exception:
            pass

    ally_set = set()
    for a in allies or []:
        if a is None:
            continue
        try:
            if isinstance(a, dict):
                p = a.get("pos", a.get("position", a.get("loc", None)))
            else:
                p = a
            ax, ay = int(p[0]), int(p[1])
            ally_set.add((ax, ay))
        except Exception:
            pass

    # Determine mode from observation if possible
    mode = g(observation, "mode", None)
    if mode is None:
        mode = g(observation, "scenario", None)
    if mode is None:
